cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry function-valued definitions', () => {
  it('validates each call against the inputSchema the definition function returns for that call', async () => {
    const executor = jest.fn(async () => 'ok');
    const requiredByCall = ['location', 'city'];
    let call = 0;
    const registry = new ToolRegistry();
    registry.register(() => {
      const required = requiredByCall[Math.min(call, requiredByCall.length - 1)];
      return {
        name: 'dynamic_weather',
        description: 'Schema changes between calls',
        inputSchema: {type: 'object', required: [required], properties: {[required]: {type: 'string'}}},
      };
    }, executor);

    const first = await registry.execute('dynamic_weather', {city: 'Paris'});
    call = 1;
    const second = await registry.execute('dynamic_weather', {city: 'Paris'});

    expect({first: first.result, second: second.result, calls: executor.mock.calls}).toEqual({
      first: expect.stringMatching(/required.*location/i),
      second: 'ok',
      calls: [[{city: 'Paris'}, undefined]],
    });
  });
});
EOF
timeout 300 npx jest src/orchestration/tools/registry.test.ts 2>&1 | grep -v console | tail -30

python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("""// The slice of ajv this registry uses, typed locally so it holds across ajv majors: 8 names an
// error's location `instancePath` and exports the class as `.default`, 6 says `dataPath` and does not.
""","""// Typed locally to hold across ajv 6 (`dataPath`, no `.default`) and 8 (`instancePath`, `.default`).
""")
s=s.replace("""function compileInputSchema(definition: ToolDefinition): ValidateFunction {
  try {
    return ajv.compile(definition.inputSchema);""","""const compiledBySchema = new WeakMap<object, ValidateFunction>();

function compileInputSchema(definition: ToolDefinition): ValidateFunction {
  const cached = compiledBySchema.get(definition.inputSchema);
  if (cached) return cached;
  try {
    const validate = ajv.compile(definition.inputSchema);
    compiledBySchema.set(definition.inputSchema, validate);
    return validate;""")
s=s.replace("""    if (tool.validate && !tool.validate(input)) {
      return {result: describeRejection(name, tool.validate)};
    }""","""    const validate = tool.validate ?? compileInputSchema(this.resolveDefinition(tool.definitionSource));
    if (!validate(input)) {
      return {result: describeRejection(name, validate)};
    }""")
open(p,'w').write(s)
EOF
